And the login function from my UsersController:

```
public function login() {
        $this->layout = 'login';
        if ($this->request->is('post')) {
            $user = $this->Auth->identify();
            if ($user) {
                // Set User Data
                $loginData = $this->Users->getLoginData($this->request->data['username'], $this->request->data['password']);
                $user['loginData'] = $loginData;
                $this->Auth->setUser($user);

                if($user['loginData']->user_type->type == 'Volunteer'){
                                // I commented this out and replaced it with a plain redirect
                       //$this->Auth->redirectUrl(['controller' => 'volunteers', 'action' => 'index']);
                       $this->redirect(['controller' => 'volunteers', 'action' => 'profile', $this->Auth->user['id']]);
            }else{
                $this->redirect(['controller' => 'users', 'action' => 'index']);
            }

                return $this->redirect($this->Auth->redirectUrl());
            } else {
                $this->Flash->error(
                    __('Username or password is incorrect. If you don\'t have an account, please register with us.'),
                    'default',
                    [],
                    'auth'
                );
            }
        }
    }
```

